(2, 1, 3, 'dokumantasyon', 0, 1, 'docs', 'Dokümantasyon', '', '<section class=\"min-h-[600px] flex flex-col items-center justify-center text-center\"><div class=\"relative mb-8 group\"><div class=\"absolute inset-0 bg-accent/20 blur-3xl rounded-full scale-150 animate-pulse\"></div><div class=\"relative size-48 md:size-64 bg-secondary border-4 border-primary rounded-full flex items-center justify-center overflow-hidden shadow-2xl transition-transform transform group-hover:scale-105 duration-500\"><img src=\"/assets/img/mnbvcxzlkjhg.jpg\" alt=\"Aether Mascot\" class=\"size-full object-cover\"></div><div class=\"absolute bottom-0 right-0 size-12 bg-primary border border-primary rounded-full aspect-square flex items-center justify-center shadow-lg animate-bounce\"><span class=\"text-xl\">✨</span></div></div><div class=\"max-w-2xl mx-auto px-4\"><h2 class=\"text-4xl md:text-6xl font-bold text-primary mb-6 tracking-tight\">AetherJS\'a <span class=\"text-accent\">Hoş Geldiniz</span></h2><p class=\"text-xl text-secondary leading-relaxed mb-8\">Geliştiriciler için tasarlanmış görünmez, hafif ve güçlü arayüz yöneticisi. Karmaşa yok, sadece özgürlük var.</p></div><div class=\"grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-3xl px-4\"><a href=\"https://github.com/xkintaro/aether-js\" target=\"_blank\" class=\"group relative p-6 bg-secondary border border-primary rounded-2xl hover:border-accent transition-all duration-300 hover:-translate-y-1 shadow-lg hover:shadow-accent/10 flex items-center gap-4 text-left\" rel=\"noopener\"><div class=\"size-12 p-3 rounded-lg bg-primary text-primary flex items-center justify-center text-2xl group-hover:scale-110 transition-transform\"><svg class=\"size-full\" viewBox=\"0 0 192 192\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\"><g id=\"SVGRepo_bgCarrier\" stroke-width=\"0\"></g><g id=\"SVGRepo_tracerCarrier\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></g><g id=\"SVGRepo_iconCarrier\"><path stroke=\"currentColor\" stroke-linec