.814 4.02 24.402 7.068 3.6 1.278 6.704 3.722 8.567 7.056 14.235 25.472 19.857 49.564 19.37 73.528-.095 4.668-2.467 8.999-6.379 11.548-11.218 7.308-21.769 11.554-31.96 15.8l-8-16m-68-8s20 10 40 10 40-10 40-10\"></path><ellipse cx=\"71\" cy=\"101\" fill=\"currentColor\" rx=\"13\" ry=\"15\"></ellipse><ellipse cx=\"121\" cy=\"101\" fill=\"currentColor\" rx=\"13\" ry=\"15\"></ellipse></g></svg></div><div><h3 class=\"text-lg font-bold text-primary group-hover:text-accent transition-colors\">Discord Sunucumuz</h3><p class=\"text-sm text-secondary\">Yardım ve sohbet için sunucumuza katılın.</p></div><div class=\"absolute right-6 opacity-0 group-hover:opacity-100 transition-opacity text-accent\">➜</div></a></div></section>', NULL, '', '', '', '2025-12-01 10:05:00', '2026-02-27 07:55:20', NULL, NULL),
(21, 1, 7, 'data-aether-trigger', 0, 0, 'docs', 'data-aether-trigger', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, bir HTML elementini (genellikle buton veya link) etkileşimli bir kontrolcüye dönüştürür. AetherJS\'in etkileşim zincirini başlatan anahtardır.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Bir elementi tetikleyici yapmak için <span class=\"highlight-marker\">data-aether-trigger</span> niteliğine bir etkileşim türü atamalısınız. Ayrıca, bu tetikleyicinin hangi elementi etkileyeceğini belirtmek için mutlaka bir <span class=\"highlight-marker\">target</span> belirtilmelidir.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;button</span> \n    <span class=\"text-code-prop highlight-marker\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"modal-1\"</span>\n<span class=\"text-code-tag\">&gt;</span>\n    ...\n<span class=\"text-code-tag\">&lt;/button&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Kabul Edilen Değerler</h2><p class=\"text-secondary mb-6\">Bu nitelik, kullanım amacına göre üç farklı değer alabilir.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Değer</th><th class=\"px-6 py-4 font-semibold\">Kullanım Amacı</th><th class=\"px-6 py-4 font-semibold\">Örnek Senaryo</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">ui-control</span></td><td class=\"px-6 py-4\">Genel amaçlı kontrolcü.</td><td class=\"px-6 py-4\">Modallar, Off-canvas menüler, Bildirim kapatma butonları.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">tab</span></td><td class=\"px-6 py-4\">Sekme değiştirici.</td><td class=\"px-6 py-4\">Tab gruplarında içerik panelleri arasında geçiş yapmak için.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">accordion</span></td><td class=\"px-6 py-4\">Genişletilebilir liste tetikleyicisi.</td><td class=\"px-6 py-4\">SSS (FAQ) sayfaları, Detaylı filtreleme menüleri.</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">03</span> Bağımlılıklar</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">Target Zorunluluğu</h4><p class=\"text-secondary leading-relaxed text-sm\">Bir elemente <span class=\"highlight-marker\">data-aether-trigger</span> verdiğinizde, sistemin hangi elementi kontrol edeceğini bilmesi gerekir.</p><p class=\"text-secondary leading-relaxed text-sm mt-3\">Bu nedenle, bu niteliği kullandığınız her yerde mutlaka <span class=\"highlight-marker\">data-aether-target=\"ID\"</span> niteliğini de tanımlamalısınız. Target değeri, kontrol edilecek HTML elementinin <strong>ID</strong>\'si olmalıdır.</p></div></div></section>', NULL, '', '', '', '2025-12-01 11:50:34', '2026-02-27 08:00:02', 2, NULL),
(22, 1, 8, 'data-aether-target', 0, 0, 'docs', 'data-aether-target', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, etkileşimin nereye uygulanacağını belirler. Bir tetikleyici (trigger) ile yönetilmek istenen HTML elementi arasındaki köprüyü kurar.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Çalışma Mantığı</h2><p class=\"text-secondary mb-6\"><span class=\"highlight-marker\">data-aether-target</span> niteliği, standart HTML ID seçicileri ile çalışır. Tetikleyiciye verdiğiniz değer, yönetilecek olan elementin <span class=\"highlight-marker\">id</span> niteliği ile birebir eşleşmelidir.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- trigger --&gt;</span>\n<span class=\"text-code-tag\">&lt;button</span> \n    <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-target</span>=<span class=\"text-code-value\">\"user-dropdown\"</span>\n<span class=\"text-code-tag\">&gt;</span>\n    ...\n<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-muted\">&lt;!-- target --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop highlight-marker\">id</span>=<span class=\"text-code-value\">\"user-dropdown\"</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden...\"</span><span class=\"text-code-tag\">&gt;</span>\n    <span class=\"text-code-muted\">...</span>\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Kullanım Alanları</h2><p class=\"text-secondary mb-6\">Bu nitelik sadece tetikleyicilerde değil, bazı durumlarda gruplayıcı elementlerde de kullanılır.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Element Tipi</th><th class=\"px-6 py-4 font-semibold\">Görevi</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Trigger (Tetikleyici)</td><td class=\"px-6 py-4\">Hangi elementin açılıp kapanacağını belirler. (En yaygın kullanım)</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Tab Butonu</td><td class=\"px-6 py-4\">Hangi sekme panelinin (Tab Panel) aktif olacağını belirler.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Accordion Header</td><td class=\"px-6 py-4\">Hangi akordeon panelinin genişletileceğini belirler.</td></tr></tbody></table></div></section>', NULL, '', '', '', '2025-12-01 12:05:54', '2026-02-27 08:12:38', 2, NULL),
(23, 1, 9, 'data-aether-action', 0, 0, 'docs', 'data-aether-action', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, tetikleyiciye tıklandığında hedef element üzerinde gerçekleştirilecek <strong>işlemin türünü</strong> belirler. Varsayılan davranış \"Aç/Kapat\" (Toggle) şeklindedir, ancak bunu zorlayıcı komutlarla değiştirebilirsiniz.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Genellikle <span class=\"highlight-marker\">ui-control</span> türündeki tetikleyicilerle birlikte kullanılır. Örneğin, bir modalın içindeki \"Kapat\" butonu için eylemi <span class=\"highlight-marker\">close</span> olarak belirtmek gerekir.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;button</span> \n    <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"notification-1\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span>\n<span class=\"text-code-tag\">&gt;</span>\n    ...\n<span class=\"text-code-tag\">&lt;/button&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Kabul Edilen Değerler</h2><p class=\"text-secondary mb-6\">AetherUI aşağıdaki aksiyon değerlerini destekler. Eğer bu niteliği boş bırakırsanız sistem otomatik olarak <span class=\"highlight-marker\">toggle</span> modunda çalışır.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Değer</th><th class=\"px-6 py-4 font-semibold\">Davranış</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">toggle</span></td><td class=\"px-6 py-4\"><span class=\"opacity-60 text-xs uppercase tracking-wide mr-2 border border-secondary px-1 rounded\">Varsayılan</span> Element açıksa kapatır, kapalıysa açar.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">open</span> / <span class=\"highlight-marker\">show</span></td><td class=\"px-6 py-4\">Elementi zorla açar/görünür yapar. Zaten açıksa işlem yapmaz.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">close</span> / <span class=\"highlight-marker\">hide</span></td><td class=\"px-6 py-4\">Elementi zorla kapatır/gizler. Zaten kapalıysa işlem yapmaz.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">remove</span></td><td class=\"px-6 py-4 text-red-400\">Hedef elementi DOM\'dan tamamen siler.</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">03</span> Özel Durum: Remove</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">DOM\'dan Silme İşlemi</h4><p class=\"text-secondary leading-relaxed text-sm\"><span class=\"highlight-marker\">action=\"remove\"</span> değeri diğerlerinden farklı çalışır. Hedef elementi gizlemek yerine HTML yapısından (DOM) tamamen siler.</p><p class=\"text-secondary leading-relaxed text-sm mt-3\">Bu özellik, \"Bir daha gösterme\" mantığıyla çalışan bilgi bannerları veya geçici uyarı kutuları için idealdir. Sayfa yenilenene kadar element geri getirilemez.</p></div></div></section>', NULL, '', '', '', '2025-12-01 12:06:13', '2026-02-27 08:13:08', 2, NULL),
(24, 1, 16, 'data-aether-sync-url', 0, 0, 'docs', 'data-aether-sync-url', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, UI durumunu tarayıcının adres çubuğu ile senkronize eder. Kullanıcı bir <span class=\"highlight-marker\">Modal</span> açtığında, URL\'in sonuna otomatik olarak <span class=\"highlight-marker\">#id</span> eklenir.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Bu bir \"Varlık Niteliği\"dir (Boolean). Genellikle Tetikleyiciler (Triggers) üzerine eklenir. Eklendiği grup içindeki etkileşimler URL hash\'ini güncellemeye başlar.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Trigger --&gt;</span>\n<span class=\"text-code-tag\">&lt;button</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\"</span>\n    <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-sync-url</span><span class=\"text-code-tag\">&gt;</span>\n    Open\n<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span>\n    <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden fixed inset-0 z-50 flex items-center justify-center p-4\"</span>\n    <span class=\"text-code-prop\">data-aether-scroll-lock</span>\n    <span class=\"text-code-prop\">data-aether-focus-trap</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Backdrop --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"absolute inset-0 bg-primary/80 backdrop-blur-sm\"</span>\n        <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n        <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n        <span class=\"text-code-prop\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span><span class=\"text-code-tag\">&gt;</span><span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Content --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"relative bg-secondary border border-primary w-full max-w-md p-6 rounded-2xl shadow-2xl scale-100 transition-all\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;h3</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-xl font-bold text-primary mb-2\"</span><span class=\"text-code-tag\">&gt;</span>Hello World<span class=\"text-code-tag\">&lt;/h3&gt;</span>\n        <span class=\"text-code-tag\">&lt;p</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-secondary mb-6\"</span><span class=\"text-code-tag\">&gt;</span>This modal updates the URL hash automatically.<span class=\"text-code-tag\">&lt;/p&gt;</span>\n\n        <span class=\"text-code-tag\">&lt;button</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 w-full cursor-pointer text-secondary hover:text-primary bg-tertiary hover:bg-tertiary-interactive rounded-lg transition-colors\"</span>\n            <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n            <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n            <span class=\"text-code-prop\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span><span class=\"text-code-tag\">&gt;</span>\n            Close\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Olaylar ve Davranış</h2><p class=\"text-secondary mb-6\">Bu özellik sadece URL\'i değiştirmekle kalmaz, URL değiştiğinde sayfayı da günceller.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Olay (Event)</th><th class=\"px-6 py-4 font-semibold\">Sonuç</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Tıklama Anı</td><td class=\"px-6 py-4\">Kullanıcı \"Profil\" butonuna tıklar -&gt; Adres çubuğu <span class=\"highlight-marker\">#profil</span> olarak güncellenir.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Paylaşım / Yenileme</td><td class=\"px-6 py-4\">Kullanıcı sayfayı yenilerse veya linki arkadaşına atarsa, AetherUI URL\'deki <span class=\"highlight-marker\">#id</span> değerini okur ve o Modalı otomatik açar.</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">03</span> Neden Kullanmalıyım?</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">Paylaşılabilirlik</h4><p class=\"text-secondary leading-relaxed text-sm\">Kullanıcılarınızın doğrudan bir <span class=\"highlight-marker\">Modal</span> açan bir link gönderebilmesini sağlar.</p></div></div></section>', NULL, '', '', '', '2025-12-01 12:06:26', '2026-02-27 08:19:02', 2, NULL),
(26, 1, 6, 'data-aether-auto', 0, 0, 'docs', 'data-aether-auto', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, AetherJS\'in \"Tak ve Çalıştır\" özelliğidir. Herhangi bir ek JavaScript yapılandırması gerektirmeden kütüphaneyi varsayılan ayarlarla ayağa kaldırır.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Bu nitelik, sayfanızın <span class=\"highlight-marker\">body</span> etiketine eklenmelidir. Kütüphane yüklendiğinde DOM üzerinde bu niteliği arar ve bulursa başlatma işlemini tetikler.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;body</span> <span class=\"text-code-prop highlight-marker\">data-aether-auto</span><span class=\"text-code-tag\">&gt;</span>\n    <span class=\"text-code-muted\">...</span>\n<span class=\"text-code-tag\">&lt;/body&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Önemli Notlar</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">Ne Zaman Kullanılmamalı?</h4><p class=\"text-secondary leading-relaxed text-sm\">Eğer kütüphanenin varsayılan ayarlarını değiştirmeniz gerekiyorsa (örneğin <span class=\"highlight-marker\">prefix</span>\'i değiştirmek veya prodüksiyon ortamında <span class=\"highlight-marker\">debug</span> modunu kapatmak istiyorsanız), <span class=\"highlight-marker\">data-aether-auto</span> özelliğini <strong>kullanmayınız</strong>.</p><p class=\"text-secondary leading-relaxed text-sm mt-3\">Bunun yerine script dosyasından sonra <span class=\"highlight-marker\">AetherUI.init({...})</span> fonksiyonunu manuel olarak çağırınız.</p></div></div></section>', NULL, '', '', '', '2025-12-02 07:38:26', '2026-02-27 07:59:31', 2, NULL),
(27, 1, 11, 'data-aether-ui', 0, 0, 'docs', 'data-aether-ui', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, standart HTML elementlerine <strong>yapısal bir kimlik</strong> kazandırır. Bir <span class=\"highlight-marker\">div</span> elementinin bir \"Tab Grubu\" mu yoksa bir \"Accordion Paneli\" mi olduğunu sisteme bildirir.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kabul Edilen Değerler</h2><p class=\"text-secondary mb-6\">Bu nitelik, bileşen tabanlı yapılar kurmak için aşağıdaki değerleri alır. Bu değerler genellikle <strong>Ebeveyn (Group)</strong> ve <strong>Çocuk (Panel)</strong> ilişkisi içinde kullanılır.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary mb-8\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Değer</th><th class=\"px-6 py-4 font-semibold\">Tür</th><th class=\"px-6 py-4 font-semibold\">Açıklama</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">tab-group</span></td><td class=\"px-6 py-4\"><span class=\"bg-blue-500/10 text-blue-500 px-2 py-1 rounded text-xs border border-blue-500/20\">Ebeveyn</span></td><td class=\"px-6 py-4\">Sekme butonlarını ve panellerini kapsayan ana konteyner.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">tab-panel</span></td><td class=\"px-6 py-4\"><span class=\"bg-green-500/10 text-green-500 px-2 py-1 rounded text-xs border border-green-500/20\">Çocuk</span></td><td class=\"px-6 py-4\">Sadece ilgili sekme tıklandığında görünen içerik alanı.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">accordion-group</span></td><td class=\"px-6 py-4\"><span class=\"bg-blue-500/10 text-blue-500 px-2 py-1 rounded text-xs border border-blue-500/20\">Ebeveyn</span></td><td class=\"px-6 py-4\">Akordeon listesini kapsayan ana konteyner.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">accordion-panel</span></td><td class=\"px-6 py-4\"><span class=\"bg-green-500/10 text-green-500 px-2 py-1 rounded text-xs border border-green-500/20\">Çocuk</span></td><td class=\"px-6 py-4\">Genişletilip daraltılabilen detay içeriği.</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Senaryo A: Tab Sistemi</h2><p class=\"text-secondary mb-6\">Sekme sistemi kurmak için kapsayıcıya <span class=\"highlight-marker\">tab-group</span> ve içeriklere <span class=\"highlight-marker\">tab-panel</span> vermelisiniz. Sistem otomatik olarak panelleri gizleyip sadece aktif olanı gösterir.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"tab-group\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Triggers --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"flex gap-4\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"tab\"</span> <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"general\"</span><span class=\"text-code-tag\">&gt;</span>General<span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"tab\"</span> <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"security\"</span><span class=\"text-code-tag\">&gt;</span>Security<span class=\"text-code-tag\">&lt;/button&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Panels --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"general\"</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"tab-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-muted\">General...</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"security\"</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"tab-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-muted\">Security...</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">03</span> Senaryo B: Accordion Sistemi</h2><p class=\"text-secondary mb-6\">Sıkça Sorulan Sorular (SSS) veya detaylı menüler için kullanılır. Varsayılan olarak bir panel açıldığında diğerleri otomatik kapanır.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-group\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Item 1 --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span> \n            <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"accordion\"</span> \n            <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"faq-1\"</span><span class=\"text-code-tag\">&gt;</span>\n            Faq 1\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"faq-1\"</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n            <span class=\"text-code-muted\">...</span>\n        <span class=\"text-code-tag\">&lt;/div&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Item 2 --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span> \n            <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"accordion\"</span> \n            <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"faq-2\"</span><span class=\"text-code-tag\">&gt;</span>\n            Faq 2\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"faq-2\"</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n            <span class=\"text-code-muted\">...</span>\n        <span class=\"text-code-tag\">&lt;/div&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section>', NULL, '', '', '', '2025-12-02 09:13:12', '2026-02-27 08:14:29', 2, NULL),
(28, 1, 10, 'data-aether-active-class-and-inactive-class', 0, 0, 'docs', 'data-aether-active-class & inactive-class', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">AetherJS varsayılan olarak stilsizdir. Bu iki nitelik, elementlerin durumlarına göre (Açık/Kapalı, Seçili/Seçisiz) CSS sınıflarını dinamik olarak değiştirmenizi sağlar.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Çalışma Prensibi</h2><p class=\"text-secondary mb-6\">Element aktif olduğunda sistem <span class=\"highlight-marker\">inactive-class</span> içindeki sınıfları kaldırır ve <span class=\"highlight-marker\">active-class</span> içindekileri ekler. Pasif duruma geçtiğinde ise tam tersini yapar.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary mb-8\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Nitelik</th><th class=\"px-6 py-4 font-semibold\">Görevi</th><th class=\"px-6 py-4 font-semibold\">Tipik Kullanım</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">data-aether-active-class</span></td><td class=\"px-6 py-4\">Element aktifken uygulanacak sınıflar.</td><td class=\"px-6 py-4\"><span class=\"font-mono text-xs bg-primary px-2 py-1 rounded border border-primary\">bg-blue-600 text-white</span> (Buton için)<br><span class=\"font-mono text-xs bg-primary px-2 py-1 rounded border border-primary mt-1 inline-block\">block</span> (Hedef için)</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">data-aether-inactive-class</span></td><td class=\"px-6 py-4\">Element pasifken uygulanacak sınıflar.</td><td class=\"px-6 py-4\"><span class=\"font-mono text-xs bg-primary px-2 py-1 rounded border border-primary\">bg-gray-200 text-gray-500</span> (Buton için)<br><span class=\"font-mono text-xs bg-primary px-2 py-1 rounded border border-primary mt-1 inline-block\">hidden</span> (Hedef için)</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Kullanım</h2><p class=\"text-secondary mb-6\">Özellikle <strong>Tab</strong> ve <strong>Accordion</strong> başlıklarında, kullanıcının hangi öğeyi seçtiğini göstermek için kullanılır.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span>\n    <span class=\"text-code-prop\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-group\"</span>\n    <span class=\"text-code-prop\">data-aether-allow-multiple</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Item 1 --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"cursor-pointer text-lg\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-active-class</span>=<span class=\"text-code-value\">\"text-accent\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-inactive-class</span>=<span class=\"text-code-value\">\"text-primary\"</span>\n            <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"accordion\"</span>\n            <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"brands\"</span><span class=\"text-code-tag\">&gt;</span>\n            Brands\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;div</span>\n            <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"brands\"</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-secondary\"</span>\n            <span class=\"text-code-prop\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n            Nike, Adidas, Puma...\n        <span class=\"text-code-tag\">&lt;/div&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Item 2 --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"cursor-pointer text-lg\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-active-class</span>=<span class=\"text-code-value\">\"text-accent\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-inactive-class</span>=<span class=\"text-code-value\">\"text-primary\"</span>\n            <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"accordion\"</span>\n            <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"sizes\"</span><span class=\"text-code-tag\">&gt;</span>\n            Sizes\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;div</span>\n            <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"sizes\"</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-secondary\"</span>\n            <span class=\"text-code-prop\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n            S, M, L, XL...\n        <span class=\"text-code-tag\">&lt;/div&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section>', NULL, '', '', '', '2025-12-02 09:20:01', '2026-02-27 08:02:47', 2, NULL);
INSERT INTO `pages` (`id`, `status`, `order`, `slug`, `is_homepage`, `menu_show`, `blade_name`, `title`, `subtitle`, `content`, `image`, `meta_title`, `meta_description`, `seo_text`, `created_at`, `updated_at`, `parent_id`, `menu_data_source`) VALUES
(29, 1, 14, 'data-aether-click-outside', 0, 0, 'docs', 'data-aether-click-outside', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, kullanıcının odaklandığı elementin dışına tıkladığını algılar ve elementi otomatik olarak kapatır. Modern web arayüzlerinde Dropdown menüler ve Modallar için vazgeçilmez bir UX standardıdır.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Bu bir \"Varlık Niteliği\"dir (Boolean). Sadece hedef elemente eklemeniz yeterlidir.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"relative\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Trigger --&gt;</span>\n    <span class=\"text-code-tag\">&lt;button</span>\n        <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\"</span>\n        <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n        <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-dropdown\"</span><span class=\"text-code-tag\">&gt;</span>\n        Open\n    <span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Dropdown Menu --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span>\n        <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"demo-dropdown\"</span>\n        <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden absolute left-0 mt-2 w-48 bg-primary border border-primary rounded-lg shadow-lg py-1 z-10\"</span>\n        <span class=\"text-code-prop highlight-marker\">data-aether-click-outside</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;a</span> <span class=\"text-code-prop\">href</span>=<span class=\"text-code-value\">\"#\"</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"block px-4 py-2 text-sm text-secondary hover:bg-secondary hover:text-primary transition-colors\"</span><span class=\"text-code-tag\">&gt;</span>Profile<span class=\"text-code-tag\">&lt;/a&gt;</span>\n        <span class=\"text-code-tag\">&lt;a</span> <span class=\"text-code-prop\">href</span>=<span class=\"text-code-value\">\"#\"</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"block px-4 py-2 text-sm text-secondary hover:bg-secondary hover:text-primary transition-colors\"</span><span class=\"text-code-tag\">&gt;</span>Settings<span class=\"text-code-tag\">&lt;/a&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Akıllı Yığın Yönetimi</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">İç İçe Elementler</h4><p class=\"text-secondary leading-relaxed text-sm\">AetherUI, açık olan pencereleri bir \"Yığın\" mantığıyla takip eder.</p><p class=\"text-secondary leading-relaxed text-sm mt-3\">Örneğin; bir Modal açıkken, onun içinden bir Dropdown açarsanız; ekrana (boşluğa) tıkladığınızda sistem <strong>önce en üstteki Dropdown\'ı kapatır</strong>. Modal açık kalmaya devam eder. İkinci tıklamada Modal kapanır.</p></div></div></section>', NULL, '', '', '', '2025-12-02 09:22:28', '2026-02-27 08:18:01', 2, NULL),
(30, 1, 15, 'data-aether-scroll-lock', 0, 0, 'docs', 'data-aether-scroll-lock', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, bir pencere açıldığında arka plandaki sayfanın (body) kaydırılmasını engeller. Kullanıcının odağını açık olan pencerede tutmak ve istenmeyen kaydırma zinciri sorununu önlemek için kullanılır.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Bu bir \"Varlık Niteliği\"dir (Boolean). Hedef elemente bu niteliği eklediğinizde, element açıldığı an body kaydırması durdurulur.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;div</span> \n    <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden fixed inset-0 z-50 flex items-center justify-center\"</span>\n    <span class=\"text-code-prop\">data-aether-click-outside</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-scroll-lock</span>\n<span class=\"text-code-tag\">&gt;</span>\n    <span class=\"text-code-muted\">...</span>\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Teknik Notlar</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">CSS Sınıfı</h4><p class=\"text-secondary leading-relaxed text-sm\">Bu özellik aktif olduğunda, sistem <span class=\"highlight-marker\">body</span> etiketine konfigürasyonda belirtilen sınıfı (Varsayılan: <span class=\"font-mono text-xs text-primary\">overflow-hidden</span>) ekler.</p><p class=\"text-secondary leading-relaxed text-sm mt-3\">Eğer Tailwind CSS kullanıyorsanız bu sınıf zaten mevcuttur. Bootstrap veya özel CSS kullanıyorsanız, bu sınıfın CSS dosyanızda tanımlı olduğundan veya AetherUI config ayarlarından değiştirdiğinizden emin olun.</p></div></div></section>', NULL, '', '', '', '2025-12-02 09:32:12', '2026-02-27 08:18:26', 2, NULL),
(31, 1, 13, 'data-aether-default-open', 0, 0, 'docs', 'data-aether-default-open', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, sayfa yüklendiğinde bir bileşenin (Tab, Accordion) varsayılan olarak <strong>açık/aktif</strong> gelmesini sağlar.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Bu bir \"Varlık Niteliği\"dir (Boolean). Genellikle <strong>Tetikleyiciler (Triggers)</strong> üzerine eklenir. Sistem başlatıldığında bu etiketi tarar ve ilgili hedefi otomatik olarak açar.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">data-aether-ui</span>=<span class=\"text-code-value\">\"tab-group\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Triggers --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"flex space-x-4\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"tab\"</span> <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"tab-1\"</span><span class=\"text-code-tag\">&gt;</span>\n            Home\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n        <span class=\"text-code-tag\">&lt;button</span> \n            <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"tab\"</span> \n            <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"tab-2\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-default-open</span><span class=\"text-code-tag\">&gt;</span>\n            Profile\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Panels --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"tab-1\"</span> <span class=\"text-code-prop\">data-aether-ui</span>=<span class=\"text-code-value\">\"tab-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-muted\">Home content...</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"tab-2\"</span> <span class=\"text-code-prop\">data-aether-ui</span>=<span class=\"text-code-value\">\"tab-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-muted\">Profile content...</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Kullanım Alanları</h2><p class=\"text-secondary mb-6\">Farklı UI desenlerinde nasıl davranış sergilediğine dair detaylar.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Bileşen</th><th class=\"px-6 py-4 font-semibold\">Davranış</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Tabs</td><td class=\"px-6 py-4\">İşaretlenen sekme içeriği gösterilir, diğerleri gizlenir. Hiçbirine verilmezse, sistem genellikle <strong>ilk</strong> sekmeyi otomatik açar.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Accordion</td><td class=\"px-6 py-4\">İşaretlenen panel genişletilmiş olarak gelir.</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">03</span> Akıllı Çakışma Yönetimi</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">URL Hash vs. Default Open</h4><p class=\"text-secondary leading-relaxed text-sm\">Eğer <span class=\"highlight-marker\">syncUrl: true</span> özelliği aktifse, AetherJS tarayıcı adres çubuğuna öncelik verir.</p><p class=\"text-secondary leading-relaxed text-sm mt-3\">Örneğin; kodunuzda \"Profil\" sekmesine <span class=\"highlight-marker\">default-open</span> vermiş olsanız bile, kullanıcı sayfaya <strong>site.com/#ayarlar</strong> linkiyle gelirse, sistem \"Profil\" yerine \"Ayarlar\" sekmesini açar. Bu, kullanıcı deneyimi açısından en doğru davranıştır.</p></div></div></section>', NULL, '', '', '', '2025-12-02 09:40:41', '2026-02-27 08:01:23', 2, NULL),
(32, 1, 17, 'data-aether-focus-trap', 0, 0, 'docs', 'data-aether-focus-trap', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Bu nitelik, klavye odağını açılan pencerenin içine hapseder. Modal açıkken <span class=\"font-mono text-sm bg-secondary px-1 rounded\">Tab</span> tuşuna basıldığında, odağın arka plandaki sayfaya kaçmasını engeller.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Kullanım</h2><p class=\"text-secondary mb-6\">Özellikle <strong>Modal</strong> pencerelerinde kullanımı zorunludur. Hedef elemente (Target) eklenir.</p></section><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"> </div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"> </div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Trigger --&gt;</span>\n<span class=\"text-code-tag\">&lt;button</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\"</span>\n    <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n    <span class=\"text-code-prop\">data-aether-sync-url</span><span class=\"text-code-tag\">&gt;</span>\n    Open\n<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span>\n    <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden fixed inset-0 z-50 flex items-center justify-center p-4\"</span>\n    <span class=\"text-code-prop\">data-aether-scroll-lock</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-focus-trap</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Backdrop --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"absolute inset-0 bg-primary/80 backdrop-blur-sm\"</span>\n        <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n        <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n        <span class=\"text-code-prop\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span><span class=\"text-code-tag\">&gt;</span><span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Content --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"relative bg-secondary border border-primary w-full max-w-md p-6 rounded-2xl shadow-2xl scale-100 transition-all\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;h3</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-xl text-center font-bold text-primary mb-2\"</span><s