INSERT INTO `pages` (`id`, `status`, `order`, `slug`, `is_homepage`, `menu_show`, `blade_name`, `title`, `subtitle`, `content`, `image`, `meta_title`, `meta_description`, `seo_text`, `created_at`, `updated_at`, `parent_id`, `menu_data_source`) VALUES
(40, 1, 20, 'modal', 0, 1, 'docs', 'Modal', '', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">Aşağıdaki bileşenler, <span class=\"highlight-marker\">AetherJS</span> kullanılarak oluşturulmuştur. Tasarım tamamen sağladığınız tema değişkenlerine (CSS Variables) dayalıdır.</p></div></section><hr class=\"border-primary my-12 opacity-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Basit Modal</h2><p class=\"text-secondary mb-6\">Scroll kilitleme (<span class=\"highlight-marker\">data-aether-scroll-lock</span>), odak hapsetme (<span class=\"highlight-marker\">data-aether-focus-trap</span>), açılışta belirli bir bileşene otomatik odaklanma (<span class=\"highlight-marker\">data-aether-autofocus</span>) ve url senkronizasyon (<span class=\"highlight-marker\">data-aether-sync-url</span>) özelliklerine sahip basit modal.</p><div class=\"min-h-[400px] p-10 bg-secondary border border-primary rounded-3xl mb-6 flex justify-center items-center\"><button class=\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\" data-aether-trigger=\"ui-control\" data-aether-target=\"example-modal-1\" data-aether-sync-url=\"\"> Open </button><div id=\"example-modal-1\" class=\"hidden fixed inset-0 z-[60] flex items-center justify-center p-4\" data-aether-scroll-lock=\"\" data-aether-focus-trap=\"\" data-aether-active-class=\"flex\" data-aether-inactive-class=\"hidden\"><div class=\"absolute inset-0 bg-primary/50 backdrop-blur-sm\" data-aether-trigger=\"ui-control\" data-aether-target=\"example-modal-1\" data-aether-action=\"close\"></div><div class=\"relative bg-secondary border border-primary w-full max-w-md p-6 rounded-2xl shadow-2xl scale-100 transition-all\"><h3 class=\"text-xl font-bold text-primary mb-2\">Confirm the Transaction</h3><p class=\"text-secondary mb-6\">This transaction cannot be undone. Are you sure you want to proceed?</p><div class=\"flex justify-end gap-3\"><button class=\"px-4 py-2 cursor-pointer text-secondary hover:text-primary hover:bg-tertiary rounded-lg transition-colors\" data-aether-trigger=\"ui-control\" data-aether-target=\"example-modal-1\" data-aether-action=\"close\"> Cancel </button> <button class=\"px-4 py-2 cursor-pointer bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors\" data-aether-autofocus=\"\"> Confirm </button></div></div></div></div><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Trigger --&gt;</span>\n<span class=\"text-code-tag\">&lt;button</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-target</span>=<span class=\"text-code-value\">\"example-modal-1\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-sync-url</span><span class=\"text-code-tag\">&gt;</span>\n    Open\n<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"example-modal-1\"</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden fixed inset-0 z-[60] flex items-center justify-center p-4\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-scroll-lock</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-focus-trap</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-active-class</span>=<span class=\"text-code-value\">\"flex\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-inactive-class</span>=<span class=\"text-code-value\">\"hidden\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Backdrop --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"absolute inset-0 bg-primary/50 backdrop-blur-sm\"</span>\n        <span class=\"text-code-prop highlight-marker\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n        <span class=\"text-code-prop highlight-marker\">data-aether-target</span>=<span class=\"text-code-value\">\"example-modal-1\"</span>\n        <span class=\"text-code-prop highlight-marker\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span><span class=\"text-code-tag\">&gt;</span><span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Content --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"relative bg-secondary border border-primary w-full max-w-md p-6 rounded-2xl shadow-2xl scale-100 transition-all\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;h3</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-xl font-bold text-primary mb-2\"</span><span class=\"text-code-tag\">&gt;</span>Confirm the Transaction<span class=\"text-code-tag\">&lt;/h3&gt;</span>\n        <span class=\"text-code-tag\">&lt;p</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-secondary mb-6\"</span><span class=\"text-code-tag\">&gt;</span>This transaction cannot be undone. Are you sure you want to proceed?<span class=\"text-code-tag\">&lt;/p&gt;</span>\n\n        <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"flex justify-end gap-3\"</span><span class=\"text-code-tag\">&gt;</span>\n            <span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer text-secondary hover:text-primary hover:bg-tertiary rounded-lg transition-colors\"</span>\n                <span class=\"text-code-prop highlight-marker\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n                <span class=\"text-code-prop highlight-marker\">data-aether-target</span>=<span class=\"text-code-value\">\"example-modal-1\"</span>\n                <span class=\"text-code-prop highlight-marker\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span><span class=\"text-code-tag\">&gt;</span>\n                Cancel\n            <span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n            <span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors\"</span>\n                <span class=\"text-code-prop highlight-marker\">data-aether-autofocus</span><span class=\"text-code-tag\">&gt;</span>\n                Confirm\n            <span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;/div&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opacity-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Çok Katmanlı (Nested)</h2><p class=\"text-secondary mb-6\">AetherUI, açık olan pencereleri bir \"Yığın\" mantığıyla yönetir.</p><div class=\"min-h-[400px] p-10 bg-secondary border border-primary rounded-3xl mb-6 flex justify-center items-center\"><button class=\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\" data-aether-trigger=\"ui-control\" data-aether-target=\"modal-level-1\" data-aether-sync-url=\"\"> Open </button><div id=\"modal-level-1\" class=\"hidden fixed inset-0 z-[60] flex items-center justify-center p-4\" data-aether-scroll-lock=\"\" data-aether-focus-trap=\"\" data-aether-active-class=\"flex\" data-aether-inactive-class=\"hidden\"><div class=\"absolute inset-0 bg-primary/50 backdrop-blur-sm\" data-aether-trigger=\"ui-control\" data-aether-target=\"modal-level-1\" data-aether-action=\"close\"></div><div class=\"relative bg-secondary border border-primary w-full max-w-lg p-0 rounded-2xl shadow-2xl overflow-hidden scale-100 transition-all\"><div class=\"p-6 border-b border-primary flex justify-between items-center bg-primary/30\"><div><h3 class=\"text-lg font-bold text-primary\">Active Projects</h3><p class=\"text-xs text-tertiary\">A total of 1 project was found</p></div><button class=\"text-tertiary cursor-pointer hover:text