INSERT INTO `translations` (`id`, `table_name`, `column_name`, `foreign_key`, `locale`, `value`, `created_at`, `updated_at`) VALUES
(544, 'pages', 'content', 39, 'en', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">AetherJS is a dependency-free JavaScript library that can be easily integrated into modern web projects. Follow the steps below to include and initialize it in your project.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Installation</h2><p class=\"text-secondary mb-6\">Download the <span class=\"highlight-marker\">aether.js</span> file to your project and include it in your page.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;script</span> <span class=\"text-code-prop\">src</span>=<span class=\"text-code-value\">\"/assets/js/aether.js\"</span><span class=\"text-code-tag\">&gt;</span><span class=\"text-code-tag\">&lt;/script&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Initialization</h2><p class=\"text-secondary mb-6\">There are two ways to initialize the library: Automatic and Manual</p><h3 class=\"text-lg font-bold text-primary mb-4\">Automatic Initialization</h3><p class=\"text-secondary mb-6\">If you want to use the default settings, you don\'t need to write any JavaScript code. Simply add the <span class=\"highlight-marker\">data-aether-auto</span> attribute to the <span class=\"highlight-marker\">body</span> tag.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;body</span> <span class=\"text-code-prop highlight-marker\">data-aether-auto</span><span class=\"text-code-tag\">&gt;</span>\n    <span class=\"text-code-muted\">...</span>\n<span class=\"text-code-tag\">&lt;/body&gt;</span></pre></div></div><h3 class=\"text-lg font-bold text-primary mb-4\">Manual Initialization</h3><p class=\"text-secondary mb-6\">If you want to customize the settings, do not use the <span class=\"highlight-marker\">data-aether-auto</span> attribute. Instead, call the <span class=\"highlight-marker\">AetherUI.init()</span> function with your own settings object after the script file.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;script&gt;</span> \n    <span class=\"text-code-prop highlight-marker\">AetherUI.init({</span>\n        <span class=\"text-code-prop\">prefix</span>: <span class=\"text-code-value\">\'aether\'</span>,\n        <span class=\"text-code-prop\">hiddenClass</span>: <span class=\"text-code-value\">\'hidden\'</span>,\n        <span class=\"text-code-prop\">blockScrollClass</span>: <span class=\"text-code-value\">\'overflow-hidden\'</span>,\n        <span class=\"text-code-prop\">themeStorageKey</span>: <span class=\"text-code-value\">\'theme\'</span>,\n        <span class=\"text-code-prop\">syncUrl</span>: <span class=\"text-code-value\">true</span>,\n        <span class=\"text-code-prop\">debug</span>: <span class=\"text-code-value\">true</span>,\n        <span class=\"text-code-prop\">domRefreshDebounce</span>: <span class=\"text-code-value\">150</span>,\n        <span class=\"text-code-prop\">resizeDebounce</span>: <span class=\"text-code-value\">300</span>,      \n    <span class=\"text-code-prop\">});</span>\n<span class=\"text-code-tag\">&lt;/script&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">03</span> Configuration</h2><p class=\"text-secondary mb-6\">The configuration object passed to the <span class=\"highlight-marker\">AetherUI.init(config)</span> method determines the global behavior of the library. Default values and descriptions are below:</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Option</th><th class=\"px-6 py-4 font-semibold\">Type</th><th class=\"px-6 py-4 font-semibold\">Default</th><th class=\"px-6 py-4 font-semibold\">Description</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">prefix</span></td><td class=\"px-6 py-4\">String</td><td class=\"px-6 py-4\">\"aether\"</td><td class=\"px-6 py-4\">Sets the prefix for all data attributes. If set to <span class=\"highlight-marker\">\"test\"</span>, <span class=\"highlight-marker\">data-test-target</span> will be used instead of <span class=\"highlight-marker\">data-aether-target</span>.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">hiddenClass</span></td><td class=\"px-6 py-4\">String</td><td class=\"px-6 py-4\">\"hidden\"</td><td class=\"px-6 py-4\">CSS class used to hide elements. Can be set to <span class=\"highlight-marker\">\"d-none\"</span> for Bootstrap users.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">blockScrollClass</span></td><td class=\"px-6 py-4\">String</td><td class=\"px-6 py-4\">\"overflow-hidden\"</td><td class=\"px-6 py-4\">Class added to the body tag to prevent scrolling when a modal is open.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">themeStorageKey</span></td><td class=\"px-6 py-4\">String</td><td class=\"px-6 py-4\">\"theme\"</td><td class=\"px-6 py-4\">Determines the localStorage key used to store the selected theme (dark/light).</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">syncUrl</span></td><td class=\"px-6 py-4\">Boolean</td><td class=\"px-6 py-4\">true</td><td class=\"px-6 py-4\">Controls whether to add a hash (#id) to the browser URL when a Tab or Modal is opened (Deep Linking).</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">debug</span></td><td class=\"px-6 py-4\">Boolean</td><td class=\"px-6 py-4\">true</td><td class=\"px-6 py-4\">Development mode. If true, logs detailed error and status messages to the console. Recommended to be false in production.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">domRefreshDebounce</span></td><td class=\"px-6 py-4\">Number</td><td class=\"px-6 py-4\">150</td><td class=\"px-6 py-4\">Trigger delay for the MutationObserver watching DOM changes (in ms).</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\"><span class=\"highlight-marker\">resizeDebounce</span></td><td class=\"px-6 py-4\">Number</td><td class=\"px-6 py-4\">300</td><td class=\"px-6 py-4\">Determines how often calculations are performed when the screen is resized (in ms).</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">04</span> Important Notice</h2><p class=\"text-secondary mb-6\">It is recommended to use the following CSS variables when testing all example codes in the documentation.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">main.css</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">@custom-variant</span> dark (&amp;:where(.dark, .dark *));\n\n<span class=\"text-code-tag\">@theme</span> {\n    <span class=\"text-code-muted\">/*----------Raw Materials----------*/</span>\n    <span class=\"text-code-prop\">--aether-50</span>: <span class=\"text-code-value\">#fafafa</span>;\n    <span class=\"text-code-prop\">--aether-100</span>: <span class=\"text-code-value\">#f4f4f5</span>;\n    <span class=\"text-code-prop\">--aether-200</span>: <span class=\"text-code-value\">#e4e4e7</span>;\n    <span class=\"text-code-prop\">--aether-300</span>: <span class=\"text-code-value\">#d4d4d8</span>;\n    <span class=\"text-code-prop\">--aether-400</span>: <span class=\"text-code-value\">#a1a1aa</span>;\n    <span class=\"text-code-prop\">--aether-500</span>: <span class=\"text-code-value\">#71717a</span>;\n    <span class=\"text-code-prop\">--aether-600</span>: <span class=\"text-code-value\">#52525b</span>;\n    <span class=\"text-code-prop\">--aether-700</span>: <span class=\"text-code-value\">#3f3f46</span>;\n    <span class=\"text-code-prop\">--aether-800</span>: <span class=\"text-code-value\">#27272a</span>;\n    <span class=\"text-code-prop\">--aether-900</span>: <span class=\"text-code-value\">#18181b</span>;\n    <span class=\"text-code-prop\">--aether-950</span>: <span class=\"text-code-value\">#121215</span>;\n\n    <span class=\"text-code-prop\">--accent</span>: <span class=\"text-code-value\">#2563eb</span>;\n    <span class=\"text-code-prop\">--accent-interactive</span>: <span class=\"text-code-value\">#3b82f6</span>;\n\n    <span class=\"text-code-prop\">--static-white</span>: <span class=\"text-code-value\">#ffffff</span>;\n    <span class=\"text-code-prop\">--static-black</span>: <span class=\"text-code-value\">#000000</span>;\n}\n\n<span class=\"text-code-muted\">/*----------Light Theme----------*/</span>\n<span class=\"text-code-tag\">:root</span> {\n    <span class=\"text-code-muted\">/* bg */</span>\n    <span class=\"text-code-prop\">--bg-primary</span>: <span class=\"text-code-value\">var(--aether-50)</span>;\n    <span class=\"text-code-prop\">--bg-primary-interactive</span>: <span class=\"text-code-value\">var(--aether-100)</span>;\n    <span class=\"text-code-prop\">--bg-secondary</span>: <span class=\"text-code-value\">var(--static-white)</span>;\n    <span class=\"text-code-prop\">--bg-secondary-interactive</span>: <span class=\"text-code-value\">var(--aether-50)</span>;\n    <span class=\"text-code-prop\">--bg-tertiary</span>: <span class=\"text-code-value\">var(--aether-100)</span>;\n    <span class=\"text-code-prop\">--bg-tertiary-interactive</span>: <span class=\"text-code-value\">var(--aether-200)</span>;\n    <span class=\"text-code-prop\">--bg-accent</span>: <span class=\"text-code-value\">var(--accent)</span>;\n    <span class=\"text-code-prop\">--bg-accent-interactive</span>: <span class=\"text-code-value\">var(--accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* fg */</span>\n    <span class=\"text-code-prop\">--fg-primary</span>: <span class=\"text-code-value\">var(--aether-900)</span>;\n    <span class=\"text-code-prop\">--fg-primary-interactive</span>: <span class=\"text-code-value\">var(--static-black)</span>;\n    <span class=\"text-code-prop\">--fg-secondary</span>: <span class=\"text-code-value\">var(--aether-600)</span>;\n    <span class=\"text-code-prop\">--fg-secondary-interactive</span>: <span class=\"text-code-value\">var(--aether-800)</span>;\n    <span class=\"text-code-prop\">--fg-tertiary</span>: <span class=\"text-code-value\">var(--aether-400)</span>;\n    <span class=\"text-code-prop\">--fg-tertiary-interactive</span>: <span class=\"text-code-value\">var(--aether-600)</span>;\n    <span class=\"text-code-prop\">--fg-inverse</span>: <span class=\"text-code-value\">var(--static-white)</span>;\n    <span class=\"text-code-prop\">--fg-inverse-interactive</span>: <span class=\"text-code-value\">var(--aether-200)</span>;\n    <span class=\"text-code-prop\">--fg-accent</span>: <span class=\"text-code-value\">var(--accent)</span>;\n    <span class=\"text-code-prop\">--fg-accent-interactive</span>: <span class=\"text-code-value\">var(--accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* border */</span>\n    <span class=\"text-code-prop\">--border-primary</span>: <span class=\"text-code-value\">var(--aether-200)</span>;\n    <span class=\"text-code-prop\">--border-primary-interactive</span>: <span class=\"text-code-value\">var(--aether-300)</span>;\n    <span class=\"text-code-prop\">--border-accent</span>: <span class=\"text-code-value\">var(--accent)</span>;\n    <span class=\"text-code-prop\">--border-accent-interactive</span>: <span class=\"text-code-value\">var(--accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* code */</span>\n    <span class=\"text-code-prop\">--code-tag</span>: <span class=\"text-code-value\">#be185d</span>; \n    <span class=\"text-code-prop\">--code-prop</span>: <span class=\"text-code-value\">#334155</span>;\n    <span class=\"text-code-prop\">--code-value</span>: <span class=\"text-code-value\">#0369a1</span>;\n    <span class=\"text-code-prop\">--code-text</span>: <span class=\"text-code-value\">#0f172a</span>; \n    <span class=\"text-code-prop\">--code-accent</span>: <span class=\"text-code-value\">#7e22ce</span>;\n    <span class=\"text-code-prop\">--code-muted</span>: <span class=\"text-code-value\">#64748b</span>; \n}\n\n<span class=\"text-code-muted\">/*----------Dark Theme----------*/</span>\n<span class=\"text-code-tag\">:root.dark</span> {\n    <span class=\"text-code-muted\">/* bg */</span>\n    <span class=\"text-code-prop\">--bg-primary</span>: <span class=\"text-code-value\">var(--aether-950)</span>;\n    <span class=\"text-code-prop\">--bg-primary-interactive</span>: <span class=\"text-code-value\">var(--aether-900)</span>;\n    <span class=\"text-code-prop\">--bg-secondary</span>: <span class=\"text-code-value\">var(--aether-900)</span>;\n    <span class=\"text-code-prop\">--bg-secondary-interactive</span>: <span class=\"text-code-value\">var(--aether-800)</span>;\n    <span class=\"text-code-prop\">--bg-tertiary</span>: <span class=\"text-code-value\">var(--aether-800)</span>;\n    <span class=\"text-code-prop\">--bg-tertiary-interactive</span>: <span class=\"text-code-value\">var(--aether-700)</span>;\n    <span class=\"text-code-prop\">--bg-accent</span>: <span class=\"text-code-value\">var(--accent)</span>;\n    <span class=\"text-code-prop\">--bg-accent-interactive</span>: <span class=\"text-code-value\">var(--accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* fg */</span>\n    <span class=\"text-code-prop\">--fg-primary</span>: <span class=\"text-code-value\">var(--aether-50)</span>;\n    <span class=\"text-code-prop\">--fg-primary-interactive</span>: <span class=\"text-code-value\">var(--static-white)</span>;\n    <span class=\"text-code-prop\">--fg-secondary</span>: <span class=\"text-code-value\">var(--aether-400)</span>;\n    <span class=\"text-code-prop\">--fg-secondary-interactive</span>: <span class=\"text-code-value\">var(--aether-200)</span>;\n    <span class=\"text-code-prop\">--fg-tertiary</span>: <span class=\"text-code-value\">var(--aether-500)</span>;\n    <span class=\"text-code-prop\">--fg-tertiary-interactive</span>: <span class=\"text-code-value\">var(--aether-300)</span>;\n    <span class=\"text-code-prop\">--fg-inverse</span>: <span class=\"text-code-value\">var(--aether-950)</span>;\n    <span class=\"text-code-prop\">--fg-inverse-interactive</span>: <span class=\"text-code-value\">var(--static-black)</span>;\n    <span class=\"text-code-prop\">--fg-accent</span>: <span class=\"text-code-value\">var(--accent)</span>;\n    <span class=\"text-code-prop\">--fg-accent-interactive</span>: <span class=\"text-code-value\">var(--accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* border */</span>\n    <span class=\"text-code-prop\">--border-primary</span>: <span class=\"text-code-value\">var(--aether-800)</span>;\n    <span class=\"text-code-prop\">--border-primary-interactive</span>: <span class=\"text-code-value\">var(--aether-700)</span>;\n    <span class=\"text-code-prop\">--border-accent</span>: <span class=\"text-code-value\">var(--accent)</span>;\n    <span class=\"text-code-prop\">--border-accent-interactive</span>: <span class=\"text-code-value\">var(--accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* code */</span>\n    <span class=\"text-code-prop\">--code-tag</span>: <span class=\"text-code-value\">#ff63aa</span>; \n    <span class=\"text-code-prop\">--code-prop</span>: <span class=\"text-code-value\">#ced8e6</span>;\n    <span class=\"text-code-prop\">--code-value</span>: <span class=\"text-code-value\">#7dd3fc</span>;\n    <span class=\"text-code-prop\">--code-text</span>: <span class=\"text-code-value\">#f4f4f5</span>;\n    <span class=\"text-code-prop\">--code-accent</span>: <span class=\"text-code-value\">#d946ef</span>;\n    <span class=\"text-code-prop\">--code-muted</span>: <span class=\"text-code-value\">#94a3b8</span>;\n}\n\n<span class=\"text-code-muted\">/*----------Tailwind Mapping----------*/</span>\n<span class=\"text-code-tag\">@theme</span> {\n    <span class=\"text-code-muted\">/* bg */</span>\n    <span class=\"text-code-prop\">--background-color-primary</span>: <span class=\"text-code-value\">var(--bg-primary)</span>;\n    <span class=\"text-code-prop\">--background-color-primary-interactive</span>: <span class=\"text-code-value\">var(--bg-primary-interactive)</span>;\n    <span class=\"text-code-prop\">--background-color-secondary</span>: <span class=\"text-code-value\">var(--bg-secondary)</span>;\n    <span class=\"text-code-prop\">--background-color-secondary-interactive</span>: <span class=\"text-code-value\">var(--bg-secondary-interactive)</span>;\n    <span class=\"text-code-prop\">--background-color-tertiary</span>: <span class=\"text-code-value\">var(--bg-tertiary)</span>;\n    <span class=\"text-code-prop\">--background-color-tertiary-interactive</span>: <span class=\"text-code-value\">var(--bg-tertiary-interactive)</span>;\n    <span class=\"text-code-prop\">--background-color-accent</span>: <span class=\"text-code-value\">var(--bg-accent)</span>;\n    <span class=\"text-code-prop\">--background-color-accent-interactive</span>: <span class=\"text-code-value\">var(--bg-accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* fg */</span>\n    <span class=\"text-code-prop\">--text-color-primary</span>: <span class=\"text-code-value\">var(--fg-primary)</span>;\n    <span class=\"text-code-prop\">--text-color-primary-interactive</span>: <span class=\"text-code-value\">var(--fg-primary-interactive)</span>;\n    <span class=\"text-code-prop\">--text-color-secondary</span>: <span class=\"text-code-value\">var(--fg-secondary)</span>;\n    <span class=\"text-code-prop\">--text-color-secondary-interactive</span>: <span class=\"text-code-value\">var(--fg-secondary-interactive)</span>;\n    <span class=\"text-code-prop\">--text-color-tertiary</span>: <span class=\"text-code-value\">var(--fg-tertiary)</span>;\n    <span class=\"text-code-prop\">--text-color-tertiary-interactive</span>: <span class=\"text-code-value\">var(--fg-tertiary-interactive)</span>;\n    <span class=\"text-code-prop\">--text-color-inverse</span>: <span class=\"text-code-value\">var(--fg-inverse)</span>;\n    <span class=\"text-code-prop\">--text-color-inverse-interactive</span>: <span class=\"text-code-value\">var(--fg-inverse-interactive)</span>;\n    <span class=\"text-code-prop\">--text-color-accent</span>: <span class=\"text-code-value\">var(--fg-accent)</span>;\n    <span class=\"text-code-prop\">--text-color-accent-interactive</span>: <span class=\"text-code-value\">var(--fg-accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* border */</span>\n    <span class=\"text-code-prop\">--border-color-primary</span>: <span class=\"text-code-value\">var(--border-primary)</span>;\n    <span class=\"text-code-prop\">--border-color-primary-interactive</span>: <span class=\"text-code-value\">var(--border-primary-interactive)</span>;\n    <span class=\"text-code-prop\">--border-color-accent</span>: <span class=\"text-code-value\">var(--border-accent)</span>;\n    <span class=\"text-code-prop\">--border-color-accent-interactive</span>: <span class=\"text-code-value\">var(--border-accent-interactive)</span>;\n\n    <span class=\"text-code-muted\">/* code */</span>\n    <span class=\"text-code-prop\">--background-color-code-tag</span>: <span class=\"text-code-value\">var(--code-tag)</span>;\n    <span class=\"text-code-prop\">--background-color-code-prop</span>: <span class=\"text-code-value\">var(--code-prop)</span>;\n    <span class=\"text-code-prop\">--background-color-code-value</span>: <span class=\"text-code-value\">var(--code-value)</span>;\n    <span class=\"text-code-prop\">--background-color-code-text</span>: <span class=\"text-code-value\">var(--code-text)</span>;\n    <span class=\"text-code-prop\">--background-color-code-accent</span>: <span class=\"text-code-value\">var(--code-accent)</span>;\n    <span class=\"text-code-prop\">--background-color-code-muted</span>: <span class=\"text-code-value\">var(--code-muted)</span>;\n\n    <span class=\"text-code-prop\">--text-color-code-tag</span>: <span class=\"text-code-value\">var(--code-tag)</span>;\n    <span class=\"text-code-prop\">--text-color-code-prop</span>: <span class=\"text-code-value\">var(--code-prop)</span>;\n    <span class=\"text-code-prop\">--text-color-code-value</span>: <span class=\"text-code-value\">var(--code-value)</span>;\n    <span class=\"text-code-prop\">--text-color-code-text</span>: <span class=\"text-code-value\">var(--code-text)</span>;\n    <span class=\"text-code-prop\">--text-color-code-accent</span>: <span class=\"text-code-value\">var(--code-accent)</span>;\n    <span class=\"text-code-prop\">--text-color-code-muted</span>: <span class=\"text-code-value\">var(--code-muted)</span>;\n}</pre></div></div></section>', '2025-12-03 09:59:20', '2026-02-27 08:09:59'),
(545, 'pages', 'content', 22, 'en', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">This attribute determines where the interaction will be applied. It builds the bridge between a trigger and the HTML element intended to be managed.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Operating Logic</h2><p class=\"text-secondary mb-6\">The <span class=\"highlight-marker\">data-aether-target</span> attribute works with standard HTML ID selectors. The value you provide to the trigger must exactly match the <span class=\"highlight-marker\">id</span> attribute of the element to be managed.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- trigger --&gt;</span>\n<span class=\"text-code-tag\">&lt;button</span> \n    <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-target</span>=<span class=\"text-code-value\">\"user-dropdown\"</span>\n<span class=\"text-code-tag\">&gt;</span>\n    ...\n<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-muted\">&lt;!-- target --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop highlight-marker\">id</span>=<span class=\"text-code-value\">\"user-dropdown\"</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden...\"</span><span class=\"text-code-tag\">&gt;</span>\n    <span class=\"text-code-muted\">...</span>\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Use Cases</h2><p class=\"text-secondary mb-6\">This attribute is used not only in triggers but also in grouping elements in certain cases.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Element Type</th><th class=\"px-6 py-4 font-semibold\">Role</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Trigger</td><td class=\"px-6 py-4\">Determines which element will be toggled. (Most common use)</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Tab Button</td><td class=\"px-6 py-4\">Determines which tab panel will become active.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Accordion Header</td><td class=\"px-6 py-4\">Determines which accordion panel will be expanded.</td></tr></tbody></table></div></section>', '2025-12-03 10:27:42', '2026-02-27 08:12:38'),
