INSERT INTO `translations` (`id`, `table_name`, `column_name`, `foreign_key`, `locale`, `value`, `created_at`, `updated_at`) VALUES
(556, 'pages', 'content', 29, 'en', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">This attribute detects when a user clicks outside of the focused element and automatically closes it. It is an essential UX standard for Dropdown menus and Modals in modern web interfaces.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Usage</h2><p class=\"text-secondary mb-6\">This is a \"Boolean Attribute.\" Simply adding it to the target element is sufficient.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"relative\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Trigger --&gt;</span>\n    <span class=\"text-code-tag\">&lt;button</span>\n        <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\"</span>\n        <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n        <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-dropdown\"</span><span class=\"text-code-tag\">&gt;</span>\n        Open\n    <span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Dropdown Menu --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span>\n        <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"demo-dropdown\"</span>\n        <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden absolute left-0 mt-2 w-48 bg-primary border border-primary rounded-lg shadow-lg py-1 z-10\"</span>\n        <span class=\"text-code-prop highlight-marker\">data-aether-click-outside</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;a</span> <span class=\"text-code-prop\">href</span>=<span class=\"text-code-value\">\"#\"</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"block px-4 py-2 text-sm text-secondary hover:bg-secondary hover:text-primary transition-colors\"</span><span class=\"text-code-tag\">&gt;</span>Profile<span class=\"text-code-tag\">&lt;/a&gt;</span>\n        <span class=\"text-code-tag\">&lt;a</span> <span class=\"text-code-prop\">href</span>=<span class=\"text-code-value\">\"#\"</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"block px-4 py-2 text-sm text-secondary hover:bg-secondary hover:text-primary transition-colors\"</span><span class=\"text-code-tag\">&gt;</span>Settings<span class=\"text-code-tag\">&lt;/a&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Smart Stack Management</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">Nested Elements</h4><p class=\"text-secondary leading-relaxed text-sm\">AetherUI tracks open windows using a \"Stack\" logic.</p><p class=\"text-secondary leading-relaxed text-sm mt-3\">For example; if a Dropdown is opened from within an active Modal, clicking on the screen (empty space) will cause the system to <strong>close the topmost Dropdown first</strong>. The Modal remains open. On the second click, the Modal will close.</p></div></div></section>', '2025-12-03 11:39:43', '2026-02-27 08:18:01'),
(557, 'pages', 'content', 24, 'en', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">This attribute synchronizes the UI state with the browser\'s address bar. When a user opens a <span class=\"highlight-marker\">Modal</span>, the <span class=\"highlight-marker\">#id</span> is automatically added to the end of the URL.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Usage</h2><p class=\"text-secondary mb-6\">This is a \"Boolean Attribute.\" It is typically added to Triggers. Interactions within the group where it is added will begin updating the URL hash.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Trigger --&gt;</span>\n<span class=\"text-code-tag\">&lt;button</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 cursor-pointer bg-primary border border-primary rounded-lg text-primary hover:text-primary-interactive hover:border-primary-interactive transition-colors flex items-center gap-2\"</span>\n    <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n    <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n    <span class=\"text-code-prop highlight-marker\">data-aether-sync-url</span><span class=\"text-code-tag\">&gt;</span>\n    Open\n<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span>\n    <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n    <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"hidden fixed inset-0 z-50 flex items-center justify-center p-4\"</span>\n    <span class=\"text-code-prop\">data-aether-scroll-lock</span>\n    <span class=\"text-code-prop\">data-aether-focus-trap</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Backdrop --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"absolute inset-0 bg-primary/80 backdrop-blur-sm\"</span>\n        <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n        <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n        <span class=\"text-code-prop\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span><span class=\"text-code-tag\">&gt;</span><span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Content --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"relative bg-secondary border border-primary w-full max-w-md p-6 rounded-2xl shadow-2xl scale-100 transition-all\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;h3</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-xl font-bold text-primary mb-2\"</span><span class=\"text-code-tag\">&gt;</span>Hello World<span class=\"text-code-tag\">&lt;/h3&gt;</span>\n        <span class=\"text-code-tag\">&lt;p</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"text-secondary mb-6\"</span><span class=\"text-code-tag\">&gt;</span>This modal updates the URL hash automatically.<span class=\"text-code-tag\">&lt;/p&gt;</span>\n\n        <span class=\"text-code-tag\">&lt;button</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-4 py-2 w-full cursor-pointer text-secondary hover:text-primary bg-tertiary hover:bg-tertiary-interactive rounded-lg transition-colors\"</span>\n            <span class=\"text-code-prop\">data-aether-trigger</span>=<span class=\"text-code-value\">\"ui-control\"</span>\n            <span class=\"text-code-prop\">data-aether-target</span>=<span class=\"text-code-value\">\"demo-modal\"</span>\n            <span class=\"text-code-prop\">data-aether-action</span>=<span class=\"text-code-value\">\"close\"</span><span class=\"text-code-tag\">&gt;</span>\n            Close\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n<span class=\"text-code-tag\">&lt;/div&gt;</span></span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Events and Behavior</h2><p class=\"text-secondary mb-6\">This feature doesn\'t just change the URL; it also updates the page when the URL changes.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Event</th><th class=\"px-6 py-4 font-semibold\">Result</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Moment of Click</td><td class=\"px-6 py-4\">User clicks the \"Profile\" button -&gt; Address bar updates to <span class=\"highlight-marker\">#profile</span>.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">Sharing / Refresh</td><td class=\"px-6 py-4\">If the user refreshes the page or sends the link to a friend, AetherUI reads the <span class=\"highlight-marker\">#id</span> value from the URL and automatically opens that Modal.</td></tr></tbody></table></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">03</span> Why Should I Use It?</h2><div class=\"p-6 rounded-2xl bg-secondary border border-primary\"><div><h4 class=\"text-primary font-bold mb-2\">Shareability</h4><p class=\"text-secondary leading-relaxed text-sm\">It allows your users to send a link that directly opens a specific <span class=\"highlight-marker\">Modal</span>.</p></div></div></section>', '2025-12-03 11:55:56', '2026-02-27 08:19:02'),
