(565, 'pages', 'title', 34, 'en', 'data-aether-theme', '2025-12-04 04:43:50', '2025-12-04 04:43:50'),
(566, 'pages', 'content', 34, 'en', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">This attribute manages the transition between your website\'s <strong>Light</strong> and <strong>Dark</strong> modes. It saves the user\'s preference to browser memory (LocalStorage) and remembers it for the next visit.</p></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Usage</h2><p class=\"text-secondary mb-6\">This attribute is typically assigned to buttons. When clicked, it adds or removes the necessary classes from the <span class=\"highlight-marker\">html</span> tag.</p><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop highlight-marker\">data-aether-theme</span>=<span class=\"text-code-value\">\"light\"</span><span class=\"text-code-tag\">&gt;</span>☀️<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop highlight-marker\">data-aether-theme</span>=<span class=\"text-code-value\">\"dark\"</span><span class=\"text-code-tag\">&gt;</span>🌙<span class=\"text-code-tag\">&lt;/button&gt;</span>\n\n<span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop highlight-marker\">data-aether-theme</span>=<span class=\"text-code-value\">\"system\"</span><span class=\"text-code-tag\">&gt;</span>🖥️<span class=\"text-code-tag\">&lt;/button&gt;</span></pre></div></div></section><hr class=\"border-primary my-12 opactiy-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">02</span> Mode Options</h2><p class=\"text-secondary mb-6\">AetherUI supports three different modes compatible with modern operating systems.</p><div class=\"overflow-hidden rounded-lg border border-primary bg-primary\"><table class=\"w-full text-left text-sm\"><thead><tr class=\"border-b border-primary bg-secondary text-primary\"><th class=\"px-6 py-4 font-semibold\">Value</th><th class=\"px-6 py-4 font-semibold\">Function</th></tr></thead><tbody class=\"divide-y divide-primary text-secondary\"><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">light</td><td class=\"px-6 py-4\">Removes the <span class=\"font-mono text-xs\">class=\"dark\"</span> class from the <span class=\"highlight-marker\">&lt;html&gt;</span> tag. Writes \'light\' to LocalStorage.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">dark</td><td class=\"px-6 py-4\">Adds the <span class=\"font-mono text-xs\">class=\"dark\"</span> class to the <span class=\"highlight-marker\">&lt;html&gt;</span> tag. Writes \'dark\' to LocalStorage.</td></tr><tr class=\"hover:bg-primary-interactive transition-colors\"><td class=\"px-6 py-4 font-mono text-primary\">system</td><td class=\"px-6 py-4\">Listens to the user\'s system preference.</td></tr></tbody></table></div></section>', '2025-12-04 04:43:50', '2026-02-27 08:20:44'),
