xt-code-value\">\"w-full px-4 py-2.5 text-sm text-secondary hover:text-primary hover:bg-primary/30 transition-colors rounded-lg flex items-center justify-between\"</span><span class=\"text-code-tag\">&gt;</span>Aether Link<span class=\"text-code-tag\">&lt;/a&gt;</span>\n                    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n                <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n            <span class=\"text-code-tag\">&lt;/div&gt;</span>\n        <span class=\"text-code-tag\">&lt;/div&gt;</span>\n\n    <span class=\"text-code-tag\">&lt;/div&gt;</span>\n<span class=\"text-code-tag\">&lt;/div&gt;</span></pre></div></div></section>', '2025-12-04 06:03:54', '2026-02-27 08:27:18'),
