INSERT INTO `translations` (`id`, `table_name`, `column_name`, `foreign_key`, `locale`, `value`, `created_at`, `updated_at`) VALUES
(573, 'pages', 'content', 42, 'en', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">The accordion components below are built with <span class=\"highlight-marker\">AetherJS</span> state management. Triggers and panels grouped within the <span class=\"highlight-marker\">data-aether-ui=\"accordion-group\"</span> container automatically operate in accordance with accessibility (ARIA) standards.</p></div></section><hr class=\"border-primary my-12 opacity-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Simple Accordion</h2><p class=\"text-secondary mb-6\">A standard accordion structure. If the <span class=\"highlight-marker\">data-aether-allow-multiple</span> attribute is not present in the container, one item closes automatically when another opens. <span class=\"highlight-marker\">data-aether-default-open</span> can be added to the item intended to be open by default.</p><div class=\"min-h-[400px] p-10 bg-secondary border border-primary rounded-3xl mb-6 flex justify-center items-center\"><div class=\"w-full max-w-lg space-y-4\" data-aether-ui=\"accordion-group\"><div class=\"border border-primary rounded-xl overflow-hidden\"><button class=\"w-full flex items-center justify-between p-4 bg-primary/20 hover:bg-primary/40 text-secondary hover:text-primary transition-colors group text-left\" data-aether-trigger=\"accordion\" data-aether-target=\"acc-item-1\" data-aether-default-open=\"\" data-aether-active-class=\"bg-primary/60 text-primary\" data-aether-inactive-class=\"bg-primary/20 text-secondary\"> <span class=\"font-medium\">What is AetherUI?</span> </button><div id=\"acc-item-1\" class=\"bg-secondary\" data-aether-ui=\"accordion-panel\"><div class=\"p-4 text-sm text-secondary leading-relaxed border-t border-primary\">AetherUI is a headless, utility-first interaction controller designed to handle complex UI states without imposing any specific styling.</div></div></div><div class=\"border border-primary rounded-xl overflow-hidden\"><button class=\"w-full flex items-center justify-between p-4 bg-primary/20 hover:bg-primary/40 text-secondary hover:text-primary transition-colors group text-left\" data-aether-trigger=\"accordion\" data-aether-target=\"acc-item-2\" data-aether-active-class=\"bg-primary/60 text-primary\" data-aether-inactive-class=\"bg-primary/20 text-secondary\"> <span class=\"font-medium\">How do I install it?</span> </button><div id=\"acc-item-2\" class=\"bg-secondary\" data-aether-ui=\"accordion-panel\"><div class=\"p-4 text-sm text-secondary leading-relaxed border-t border-primary\">Simply include the script in your project. It initializes automatically on DOM content loaded for elements with the auto-init attribute.</div></div></div><div class=\"border border-primary rounded-xl overflow-hidden\"><button class=\"w-full flex items-center justify-between p-4 bg-primary/20 hover:bg-primary/40 text-secondary hover:text-primary transition-colors group text-left\" data-aether-trigger=\"accordion\" data-aether-target=\"acc-item-3\" data-aether-active-class=\"bg-primary/60 text-primary\" data-aether-inactive-class=\"bg-primary/20 text-secondary\"> <span class=\"font-medium\">Is it accessible?</span> </button><div id=\"acc-item-3\" class=\"bg-secondary\" data-aether-ui=\"accordion-panel\"><div class=\"p-4 text-sm text-secondary leading-relaxed border-t border-primary\">Yes! AetherUI automatically manages ARIA attributes like aria-expanded, aria-hidden, and aria-controls for you.</div></div></div></div></div><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"w-full max-w-lg space-y-4\"</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-group\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Item 1 --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"border border-primary rounded-xl overflow-hidden\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"w-full flex items-center justify-between p-4 bg-primary/20 hover:bg-primary/40 text-secondary hover:text-primary transition-colors group text-left\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-trigger</span>=<span class=\"text-code-value\">\"accordion\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-target</span>=<span class=\"text-code-value\">\"acc-item-1\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-default-open</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-active-class</span>=<span class=\"text-code-value\">\"bg-primary/60 text-primary\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-inactive-class</span>=<span class=\"text-code-value\">\"bg-primary/20 text-secondary\"</span><span class=\"text-code-tag\">&gt;</span>\n            <span class=\"text-code-tag\">&lt;span</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"font-medium\"</span><span class=\"text-code-tag\">&gt;</span>What is AetherUI?<span class=\"text-code-tag\">&lt;/span&gt;</span>\n            <span class=\"text-code-tag\">&lt;svg</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"size-5 transition-transform duration-300 group-aria-expanded:rotate-180 opacity-70\"</span> <span class=\"text-code-prop\">fill</span>=<span class=\"text-code-value\">\"none\"</span> <span class=\"text-code-prop\">viewBox</span>=<span class=\"text-code-value\">\"0 0 24 24\"</span> <span class=\"text-code-prop\">stroke</span>=<span class=\"text-code-value\">\"currentColor\"</span><span class=\"text-code-tag\">&gt;</span>\n                <span class=\"text-code-tag\">&lt;path</span> <span class=\"text-code-prop\">stroke-linecap</span>=<span class=\"text-code-value\">\"round\"</span> <span class=\"text-code-prop\">stroke-linejoin</span>=<span class=\"text-code-value\">\"round\"</span> <span class=\"text-code-prop\">stroke-width</span>=<span class=\"text-code-value\">\"2\"</span> <span class=\"text-code-prop\">d</span>=<span class=\"text-code-value\">\"M19 9l-7 7-7-7\"</span> <span class=\"text-code-tag\">/&gt;</span>\n            <span class=\"text-code-tag\">&lt;/svg&gt;</span>\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">id</span>=<span class=\"text-code-value\">\"acc-item-1\"</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"bg-secondary\"</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"accordion-panel\"</span><span class=\"text-code-tag\">&gt;</span>\n            <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"p-4 text-s