INSERT INTO `translations` (`id`, `table_name`, `column_name`, `foreign_key`, `locale`, `value`, `created_at`, `updated_at`) VALUES
(577, 'pages', 'content', 43, 'en', '<section><div class=\"mt-6 mb-12\"><p class=\"text-lg text-secondary leading-relaxed\">The tab components below are built using <span class=\"highlight-marker\">AetherJS</span> state management. The <span class=\"highlight-marker\">data-aether-ui=\"tab-group\"</span> container automatically pairs the triggers and panels within it. AetherUI manages accessibility attributes such as <span class=\"text-code-prop\">role</span>, <span class=\"text-code-prop\">aria-selected</span>, and <span class=\"text-code-prop\">aria-hidden</span> for you.</p></div></section><hr class=\"border-primary my-12 opacity-50\"><section><h2 class=\"text-2xl font-bold text-primary mb-4 flex items-center gap-3\"><span class=\"flex items-center justify-center size-8 rounded bg-secondary text-accent text-sm font-mono border border-accent\">01</span> Simple Tab</h2><p class=\"text-secondary mb-6\">A standard tab structure. The <span class=\"highlight-marker\">data-aether-default-open</span> attribute is added to the trigger intended to be open by default.</p><div class=\"min-h-[400px] p-10 bg-secondary border border-primary rounded-3xl mb-6 flex justify-center items-center\"><div class=\"w-full max-w-2xl\" data-aether-ui=\"tab-group\"><div class=\"flex border-b border-primary mb-6\"><button class=\"px-6 py-3 text-sm font-medium border-b-2 transition-colors duration-200\" data-aether-trigger=\"tab\" data-aether-target=\"tab-overview\" data-aether-default-open=\"\" data-aether-active-class=\"border-accent text-accent\" data-aether-inactive-class=\"border-transparent text-secondary hover:text-primary hover:border-primary-interactive\"> Overview </button> <button class=\"px-6 py-3 text-sm font-medium border-b-2 transition-colors duration-200\" data-aether-trigger=\"tab\" data-aether-target=\"tab-features\" data-aether-active-class=\"border-accent text-accent\" data-aether-inactive-class=\"border-transparent text-secondary hover:text-primary hover:border-primary-interactive\"> Features </button> <button class=\"px-6 py-3 text-sm font-medium border-b-2 transition-colors duration-200\" data-aether-trigger=\"tab\" data-aether-target=\"tab-pricing\" data-aether-active-class=\"border-accent text-accent\" data-aether-inactive-class=\"border-transparent text-secondary hover:text-primary hover:border-primary-interactive\"> Pricing </button></div><div class=\"bg-secondary rounded-2xl p-6 min-h-[160px] border border-primary\"><div id=\"tab-overview\" data-aether-ui=\"tab-panel\"><h3 class=\"text-lg font-bold text-primary mb-2\">Project Overview</h3><p class=\"text-sm text-secondary leading-relaxed\">AetherUI provides a set of unstyled, accessible UI primitives for building robust web applications. It handles the logic, you handle the design.</p></div><div id=\"tab-features\" data-aether-ui=\"tab-panel\"><h3 class=\"text-lg font-bold text-primary mb-2\">Key Features</h3><ul class=\"text-sm text-secondary space-y-2 list-disc list-inside\"><li>Headless Architecture</li><li>WAI-ARIA Compliant</li><li>Tiny Footprint</li></ul></div><div id=\"tab-pricing\" data-aether-ui=\"tab-panel\"><h3 class=\"text-lg font-bold text-primary mb-2\">Simple Pricing</h3><p class=\"text-sm text-secondary leading-relaxed\">Open source and free for personal and commercial projects under the MIT license.</p></div></div></div></div><div class=\"bg-secondary rounded-3xl border border-primary overflow-hidden mb-8\"><div class=\"flex items-center justify-between px-6 py-4 border-b border-primary\"><div class=\"flex space-x-2\"><div class=\"w-3 h-3 rounded-full bg-red-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-amber-400/80\"></div><div class=\"w-3 h-3 rounded-full bg-green-400/80\"></div></div><div class=\"text-xs text-tertiary font-mono\">index.html</div></div><div class=\"bg-primary p-6 max-h-[600px] overflow-auto\"><pre class=\"font-mono text-[13px] leading-6 text-code-prop\"><span class=\"text-code-muted\">&lt;!-- Wrapper --&gt;</span>\n<span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"w-full max-w-2xl\"</span> <span class=\"text-code-prop highlight-marker\">data-aether-ui</span>=<span class=\"text-code-value\">\"tab-group\"</span><span class=\"text-code-tag\">&gt;</span>\n\n    <span class=\"text-code-muted\">&lt;!-- Tab List --&gt;</span>\n    <span class=\"text-code-tag\">&lt;div</span> <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"flex border-b border-primary mb-6\"</span><span class=\"text-code-tag\">&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-6 py-3 text-sm font-medium border-b-2 transition-colors duration-200\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-trigger</span>=<span class=\"text-code-value\">\"tab\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-target</span>=<span class=\"text-code-value\">\"tab-overview\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-default-open</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-active-class</span>=<span class=\"text-code-value\">\"border-accent text-accent\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-inactive-class</span>=<span class=\"text-code-value\">\"border-transparent text-secondary hover:text-primary hover:border-primary-interactive\"</span><span class=\"text-code-tag\">&gt;</span>\n            Overview\n        <span class=\"text-code-tag\">&lt;/button&gt;</span>\n        <span class=\"text-code-tag\">&lt;button</span>\n            <span class=\"text-code-prop\">class</span>=<span class=\"text-code-value\">\"px-6 py-3 text-sm font-medium border-b-2 transition-colors duration-200\"</span>\n            <span class=\"text-code-prop highlight-marker\">data-aether-trigger</span